#!/usr/bin/env node
/**
 * Stamps app.json with the version from package.json and a fresh build number.
 * The android/ and ios/ folders are generated by `expo prebuild` from app.json, so they are
 * never edited by hand.
 *
 * Build number format: YYMMDDhh  (e.g. 26050114 for 2026-05-01 at 14:xx)
 *
 * Fields updated in app.json:
 *   expo.version
 *   expo.android.versionCode  (number)
 *   expo.ios.buildNumber      (string)
 */

const fs = require('fs');
const path = require('path');

const ROOT = path.resolve(__dirname, '..');

function buildNumber() {
  const now = new Date();
  const yy = String(now.getFullYear()).slice(-2);
  const mm = String(now.getMonth() + 1).padStart(2, '0');
  const dd = String(now.getDate()).padStart(2, '0');
  const hh = String(now.getHours()).padStart(2, '0');
  return `${yy}${mm}${dd}${hh}`;
}

const pkg = JSON.parse(
  fs.readFileSync(path.join(ROOT, 'package.json'), 'utf8'),
);
const appJsonPath = path.join(ROOT, 'app.json');
const appJson = JSON.parse(fs.readFileSync(appJsonPath, 'utf8'));

const version = pkg.version;
const build = buildNumber();

appJson.expo.version = version;
appJson.expo.android = {...appJson.expo.android, versionCode: Number(build)};
appJson.expo.ios = {...appJson.expo.ios, buildNumber: build};

fs.writeFileSync(appJsonPath, `${JSON.stringify(appJson, null, 2)}\n`, 'utf8');

console.log(`\nVersion:  ${version}`);
console.log(`Build:    ${build}`);
console.log(
  'Updated:  app.json (expo.version, android.versionCode, ios.buildNumber)\n',
);
